package com.acis.terain_photo.security;
import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.io.IOException;import java.util.List;
@Component public class JwtFilter extends OncePerRequestFilter {private final SecretKey key;public JwtFilter(@Value("${jwt.secret}")String s){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));} @Override protected void doFilterInternal(HttpServletRequest q,HttpServletResponse r,FilterChain c)throws ServletException,IOException{String h=q.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var p=Jwts.parser().verifyWith(key).build().parseSignedClaims(h.substring(7)).getPayload();String e=p.get("email",String.class),role=p.get("rol",String.class);if(e!=null&&role!=null)SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(e,null,List.of(new SimpleGrantedAuthority("ROLE_"+role))));}catch(Exception ignored){SecurityContextHolder.clearContext();}c.doFilter(q,r);}}
